/* @autogenerated */
import { ContextValue } from '@shared/context/state/app-state.service';
import { ContextReferences, contextBindings, contextFields, injectContext, scopeQuery } from './context-filter';

describe('context filter', () => {
  const device: ContextReferences = {
    references: {
      project: { entity: 'project', filter: 'projects' },
      type: { entity: 'device-type', filter: 'types' },
    },
  };
  // Dos referencias al mismo cliente: el propietario es el campo por defecto
  const asset: ContextReferences = {
    references: {
      owner: { entity: 'client', filter: 'owners' },
      testing: { entity: 'client', filter: 'testings' },
    },
    contextFields: { client: 'owner' },
  };

  describe('contextBindings', () => {
    it('applies an entity context to the field that references it, whatever its name', () => {
      const bindings = contextBindings(device, { kind: ContextValue.fixed('kind', { $ref: 't1' }, 'device-type') });
      expect(bindings.map((b) => [b.field, b.filter, b.values])).toEqual([['type', 'types', ['t1']]]);
    });

    it('uses the default field when several fields reference the entity', () => {
      const bindings = contextBindings(asset, { client: ContextValue.fixed('client', 'c1', 'client') });
      expect(bindings.map((b) => b.field)).toEqual(['owner']);
    });

    it('falls back to the field named like the key, and to none when still ambiguous', () => {
      const plain: ContextReferences = { references: asset.references };
      expect(contextBindings(plain, { testing: ContextValue.fixed('testing', 'c1', 'client') })[0].field).toBe(
        'testing',
      );
      expect(contextBindings(plain, { client: ContextValue.fixed('client', 'c1', 'client') })).toEqual([]);
    });

    it('matches by name without entity, and ignores entities that are not referenced', () => {
      expect(contextBindings(device, { project: ContextValue.fixed('project', 'p1') })[0].field).toBe('project');
      expect(contextBindings(device, { vendor: ContextValue.fixed('vendor', 'v1', 'vendor') })).toEqual([]);
      expect(contextBindings(device, { project: null })).toEqual([]);
    });
  });

  describe('scopeQuery', () => {
    const scope = (query: any, ctx: ContextValue) => scopeQuery(query, contextBindings(device, { k: ctx }));

    it('moves the context to the multiple filter of the field', () => {
      expect(scope({ limit: 5 }, ContextValue.fixed('k', 'p1', 'project'))).toEqual({ limit: 5, projects: ['p1'] });
    });

    it('intersects with what the query already asks for that field', () => {
      const ctx = ContextValue.filter('k', ['p1', 'p2'], 'project');
      expect(scope({ projects: ['p2', 'p3'] }, ctx)).toEqual({ projects: ['p2'] });
      expect(scope({ project: 'p1' }, ctx)).toEqual({ projects: ['p1'] });
      expect(scope({ project: 'p9' }, ctx)).toBeNull();
    });

    it('leaves the query alone for empty or non filtering contexts', () => {
      expect(scope({ a: 1 }, ContextValue.fixed('k', null, 'project'))).toEqual({ a: 1 });
      expect(scope({ a: 1 }, ContextValue.default('k', 'p1', 'project'))).toEqual({ a: 1 });
    });
  });

  describe('injectContext', () => {
    const inject = (item: any, ctx: ContextValue) => injectContext(item, contextBindings(asset, { client: ctx }));

    it('imposes fixed values on the default field', () => {
      expect(inject({ owner: { $ref: 'x' } }, ContextValue.fixed('client', { $ref: 'c1' }, 'client'))).toEqual({
        owner: { $ref: 'c1' },
      });
    });

    it('fills only empty fields with default values', () => {
      const ctx = ContextValue.default('client', 'c1', 'client');
      expect(inject({}, ctx)).toEqual({ owner: { $ref: 'c1' } });
      expect(inject({ owner: { $ref: 'x' } }, ctx)).toEqual({ owner: { $ref: 'x' } });
    });

    it('does not inject filters, empty values or several values', () => {
      expect(inject({}, ContextValue.filter('client', 'c1', 'client'))).toEqual({});
      expect(inject({}, ContextValue.fixed('client', null, 'client'))).toEqual({});
      expect(inject({}, ContextValue.fixed('client', ['c1', 'c2'], 'client'))).toEqual({});
    });
  });

  describe('contextFields', () => {
    it('splits fixed, default and filtered fields', () => {
      const fields = contextFields(
        contextBindings(device, {
          project: ContextValue.fixed('project', { $ref: 'p1' }, 'project'),
          kind: ContextValue.default('kind', 't1', 'device-type'),
        }),
      );
      expect(fields).toEqual({
        fixed: { project: { $ref: 'p1' } },
        defaults: { type: { $ref: 't1' } },
        filtered: ['project', 'projects'],
      });
    });

    it('filters with several values without fixing them', () => {
      const fields = contextFields(contextBindings(device, { k: ContextValue.fixed('k', ['p1', 'p2'], 'project') }));
      expect(fields).toEqual({ fixed: {}, defaults: {}, filtered: ['project', 'projects'] });
    });
  });
});
